[CmdletBinding()]param([string]$ProjectRoot=".",[Parameter(Mandatory=$true)][string]$TargetHead,[Parameter(Mandatory=$true)][string]$ImplementationContextId,[Parameter(Mandatory=$true)][string]$ReviewerContextId,[Parameter(Mandatory=$true)][string]$ImplementationRoot,[Parameter(Mandatory=$true)][string]$ReviewerRoot,[Parameter(Mandatory=$true)][string]$ArtifactManifestPath,[ValidateSet("protected_reviewer","external_validator","implementation_context")][string]$PredicateOrigin="protected_reviewer",[switch]$ReviewerAuthoredImplementation,[switch]$ReviewerAuthoredArtifactGenerator,[switch]$ReviewerAuthoredPredicates,[switch]$Apply)
$ErrorActionPreference="Stop";$Root=(Resolve-Path $ProjectRoot).Path;$Wi=Get-Content (Join-Path $Root ".agy\WORK_ITEM.json") -Raw|ConvertFrom-Json;$Manifest=(Resolve-Path $ArtifactManifestPath).Path;$Errors=@();if($ImplementationContextId-eq$ReviewerContextId){$Errors+="SAME_CONTEXT"};if([IO.Path]::GetFullPath($ImplementationRoot).TrimEnd('\')-eq[IO.Path]::GetFullPath($ReviewerRoot).TrimEnd('\')){$Errors+="SAME_MUTABLE_ROOT"};if($PredicateOrigin-eq"implementation_context"){$Errors+="SELF_AUTHORED_PREDICATES"};if($ReviewerAuthoredImplementation -or $ReviewerAuthoredArtifactGenerator -or $ReviewerAuthoredPredicates){$Errors+="REVIEWER_NOT_INDEPENDENT"}
$Status=if($Errors.Count){"not_independent"}else{"independent"};$A=[ordered]@{schema_version="1.0.0";work_item_id=[string]$Wi.work_item_id;target_head=$TargetHead;implementation_context_id=$ImplementationContextId;reviewer_context_id=$ReviewerContextId;implementation_root=[IO.Path]::GetFullPath($ImplementationRoot);reviewer_root=[IO.Path]::GetFullPath($ReviewerRoot);read_only=$true;artifact_manifest_sha256=(Get-FileHash $Manifest -Algorithm SHA256).Hash.ToLowerInvariant();predicate_origin=$PredicateOrigin;reviewer_authored_implementation=[bool]$ReviewerAuthoredImplementation;reviewer_authored_artifact_generator=[bool]$ReviewerAuthoredArtifactGenerator;reviewer_authored_predicates=[bool]$ReviewerAuthoredPredicates;independence_status=$Status;generated_at_utc=(Get-Date).ToUniversalTime().ToString("o")}
$Out=Join-Path $Root ".agy\REVIEWER_ATTESTATION.json";if($Apply){[IO.File]::WriteAllText($Out,($A|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Write-Host "Reviewer attestation: $Status"}else{$A|ConvertTo-Json -Depth 20};if($Errors.Count){exit 1}
